{"ts_source": "export interface OrderState { state: 'Pending' | 'Processing' | 'Completed'; }
export function transition(current: OrderState): OrderState {
  if (current.state === 'Pending') return { state: 'Processing' };
  if (current.state === 'Processing') return { state: 'Completed' };
  return current;
}"}
